using namespace metal;

kernel void liquidGlassDispersion(
    texture2d<float, access::read> inTexture [[texture(0)]],
    texture2d<float, access::write> outTexture [[texture(1)]],
    uint2 id [[thread_position_in_grid]])
{
    if (id.x >= outTexture.get_width() || id.y >= outTexture.get_height()) return;
    float2 uv = float2(id) / float2(outTexture.get_width(), outTexture.get_height());
    float2 offset = (uv - 0.5) * 0.008;
    float r = inTexture.read(uint2(id.x + offset.x * 100.0, id.y + offset.y * 100.0)).r;
    float g = inTexture.read(id).g;
    float b = inTexture.read(uint2(id.x - offset.x * 100.0, id.y - offset.y * 100.0)).b;
    outTexture.write(float4(r, g, b, 1.0), id);
}
