use std::simd::f32x8;

pub fn simd_cosine_similarity(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(a.len(), b.len());
    let mut dot = 0.0f32;
    let mut norm_a = 0.0f32;
    let mut norm_b = 0.0f32;
    let chunks = a.len() / 8;
    for i in 0..chunks {
        let va = f32x8::from_slice(&a[i*8..(i+1)*8]);
        let vb = f32x8::from_slice(&b[i*8..(i+1)*8]);
        dot += (va * vb).reduce_sum();
        norm_a += (va * va).reduce_sum();
        norm_b += (vb * vb).reduce_sum();
    }
    dot / (norm_a.sqrt() * norm_b.sqrt() + 1e-8)
}
